import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import Header from "../components/header";
import Footer from "../components/footer";
import "./Results.css";
const Results = () => {
  const location = useLocation();
  const query = location.state?.query;

  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      if (!query) {
        setLoading(false);
        return;
      }

      try {
        const response = await fetch(
          `http://localhost:5000/api/search?q=${query}`
        );

        const data = await response.json();

        console.log("FULL API RESPONSE:", data);

        const results =
          data?.shopping_results ||
          data?.organic_results ||
          data?.inline_shopping_results ||
          [];

        const formatted = results.slice(0, 40).map((item) => ({
          title: item.title || "No Title",
          price: item.price || "N/A",
          rating: item.rating || "N/A",
          image: item.thumbnail || item.image || "",
          link:
            item.link ||
            item.product_link ||
            item.offer_link ||
            item.source_link ||
            "#",
          source: item.source || "Unknown",
        }));

        setProducts(formatted);
      } catch (error) {
        console.log("ERROR:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [query]);

  const addToFavorite = (product) => {
    let fav = JSON.parse(localStorage.getItem("favorites")) || [];

    const exists = fav.find((item) => item.link === product.link);
    if (exists) {
      alert("Already in favorites!");
      return;
    }

    fav.push(product);
    localStorage.setItem("favorites", JSON.stringify(fav));
    alert("Added to favorites!");
  };

  return (
    <>
      <Header />

      <div style={{ padding: "20px" }}>
        <h2>Results</h2>
        <p>Search: {query}</p>

        {loading ? (
          <p>Loading...</p>
        ) : products.length === 0 ? (
          <p>No products found 😢</p>
        ) : (
          <div className="products-grid">

            {products.map((item, index) => (
              <div className="product-card" key={index}>

                {item.image && (
                  <img
                    src={item.image}
                    alt={item.title}
                    className="product-img"
                  />
                )}

                <h3 className="product-title">{item.title}</h3>

                <p><b>Price:</b> {item.price}</p>
                <p><b>Rating:</b> {item.rating}</p>
                <p><b>Source:</b> {item.source}</p>

                <div className="btn-group">

                  <button onClick={() => addToFavorite(item)}>
                    Add to Favorite
                  </button>

                  <button
                    onClick={() => {
                      if (item.link && item.link !== "#") {
                        window.location.href = `/redirect?url=${encodeURIComponent(item.link)}`;
                      } else {
                        alert("Link not available");
                      }
                    }}
                  >
                    Go to Website
                  </button>

                </div>

              </div>
            ))}

          </div>
        )}
      </div>

      <Footer />
    </>
  );
};

export default Results;
